        for i in range(k//2):
            arr[i], arr[k-i-1] = arr[k-i-1], arr[i]

    for i in range(len(arr)-1, 0, -1):
        max_idx = 0
        for j in range(i+1):
            if arr[j] > arr[max_idx]:
                max_idx = j
        flip(arr, max_idx+1)
        flip(arr, i+1)
    return arr

